mapper.select:
SELECT DISTINCT
p.permission_name,p.id,p.parent_id,p.menu_url,p.menu_icon,p.permission_type,p.version,
p.permission_code,p.sort_number,p.operable,p.component,p.cache,p.link,p.usable,p.device,p.app_id,p.tenant_id
FROM upm_user u,upm_user_role ur,upm_permission p,upm_role_permission rp

    u.id = ur.user_id AND ur.role_id = rp.role_id
    AND rp.permission_id = p.id AND u.deleted = 0 and p.deleted = 0
    AND p.device = #{device}
    AND p.app_id = #{appId}
    AND u.id = #{userId}
    ORDER BY p.sort_number asc, p.id asc

SELECT DISTINCT p.id
FROM upm_user u
INNER JOIN upm_user_role ur ON ur.user_id = u.id AND ur.tenant_id = u.tenant_id
INNER JOIN upm_role r ON r.id = ur.role_id AND r.tenant_id = u.tenant_id
INNER JOIN upm_role_permission rp ON rp.role_id = r.id AND rp.tenant_id = u.tenant_id
INNER JOIN upm_permission p ON p.id = rp.permission_id AND p.tenant_id = u.tenant_id
WHERE u.id = #{userId} AND u.deleted = #{notDeleted}
  AND r.deleted = #{notDeleted} AND r.usable = #{usable}
  AND p.deleted = #{notDeleted} AND p.usable = #{usable}
  AND p.device = #{device} AND p.app_id = #{appId}
